#include <stdio.h>
/*
 * ex10：超标量（多发射）能带来多少 IPC 与加速比
 * 概念：
 *   单发射：每拍最多启动 1 条指令 -> IPC 上限 1；
 *   超标量宽度 w：每拍最多启动 w 条 -> IPC 上限 w；
 *   实际 IPC = w × 发射槽利用率 u（受依赖、资源冲突、分支限制）。
 * 本程序算实际 IPC、完成 n 条指令所需周期与相对单发射的加速比。
 */
int main(void) {
    int w = 2;              /* 超标量宽度：每拍最多发射 2 条 */
    int n = 100;            /* 待执行指令数 */
    double u = 0.70;        /* 发射槽利用率（实测值，非理论值）*/

    double ipc_ideal = (double)w;         /* 理想 IPC */
    double ipc_real  = w * u;             /* 实际 IPC */
    double cycles    = n / ipc_real;      /* 实际完成周期（含小数）*/
    int    cycles_i  = (int)(cycles + 0.999999);   /* 向上取整 */
    int    cycles_single = n;             /* 单发射：每拍 1 条 */

    printf("超标量宽度 w=%d, 指令数 n=%d, 发射槽利用率 u=%.2f\n", w, n, u);
    printf("理想IPC=%d (单周期发%d条) ; 实际IPC=%.2f\n", w, w, ipc_real);
    printf("单发射周期=%d ; 超标量周期≈%d\n", cycles_single, cycles_i);
    printf("相对单发射加速比=%.2f 倍\n", (double)cycles_single / cycles_i);
    return 0;
}
